  /** Lista completa de imóveis (no site real: o resultado da última leitura do XML). */
  function carregarImoveis() { return B.imoveis.slice(); }

  /** Busca exata pelo código. Aceita "LP-1012", "lp1012" ou só "1012". */
  function obterImovelPorCodigo(cod) {
    var c = String(cod || '').toUpperCase().replace(/\s/g, '');
    var m = c.match(/^(?:LP-?)?(\d{3,5})$/);
    if (m) c = 'LP-' + m[1];
    return porCod[c] || null;
  }

  function obterCorretores() { return B.corretores.slice(); }
  function obterCorretor(id) { return porCor[id] || null; }
  function obterBairros() { return B.bairros.slice(); }

  var num = function (v) { var n = parseFloat(String(v == null ? '' : v).replace(/\./g, '').replace(',', '.')); return isNaN(n) ? null : n; };
