    var tipos = lista(f.tipo), bairros = lista(f.bairro).map(semAcento), favs = f.favoritos ? lista(f.favoritos) : null;
    var lim = function (campo, a, b) { a = num(a); b = num(b); return function (i) { return (a == null || i[campo] >= a) && (b == null || i[campo] <= b); }; };
