      function (i) { return !num(f.vagas) || i.vagas >= num(f.vagas); },
      function (i) { return ['pet', 'mobiliado', 'varanda', 'piscina', 'elevador', 'novo', 'condominioFechado'].every(function (k) { return !f[k] || i[k]; }); },
      function (i) { return !f.corretor || i.corretor === f.corretor; },
