  // ---------------- leads e rodízio ----------------
  var ORIGENS = ['Site · página do imóvel', 'ZAP Imóveis', 'Viva Real', 'WhatsApp', 'Imovelweb', 'OLX', 'Instagram', 'Placa no imóvel', 'Chaves na Mão', 'Indicação'];
